insert into pops_registros (colecao, id, registro, atualizado_em) values ('pops', 'pop-cmp-01', $json${"id": "pop-cmp-01", "codigo": "POP-CMP-01", "setor": "Compras e almoxarifado", "titulo": "Compra de material e entrada no estoque", "objetivo": "Material certo, na quantidade certa, antes de a produção parar — e com o custo lançado no centro certo.", "responsavel": "Comprador / Almoxarife", "epis": ["Luva (movimentação de chapa)", "Sapato fechado"], "blocos": [{"tipo": "subtitulo", "texto": "Quando se aplica"}, {"tipo": "lista", "itens": ["Pedido de material do PCP ou de qualquer setor de produção.", "Reposição de item de giro que bateu no mínimo.", "Compra específica de O.S. (material que não é de estoque)."]}, {"tipo": "subtitulo", "texto": "O que a Impresilk compra"}, {"tipo": "lista", "itens": ["Chapas: ACM, acrílico, PVC expandido, poliondas, MDF.", "Impressos: vinil adesivo, lona, laminação, ribbon.", "Perfis de alumínio, metalon, chapa de aço e inox.", "LED, fontes, cabos e ferragens.", "Consumíveis: fresa, lâmina, bico, gás, tinta, cola, fita, rebite, bucha."]}, {"tipo": "subtitulo", "texto": "Passo a passo"}, {"tipo": "passos", "itens": ["Receber a solicitação com: material, especificação (espessura, cor, marca), quantidade e a O.S. (quando for de pedido).", "Conferir o ESTOQUE antes de cotar — comprar o que já tem é dinheiro parado duas vezes.", "Cotar com no mínimo 2 fornecedores para item acima do valor definido pela direção; abaixo disso, fornecedor homologado direto.", "Comparar preço, PRAZO e frete juntos: o mais barato que chega depois da entrega não é o mais barato.", "Emitir a ordem de compra e registrar no Mubisys, com a O.S. quando for material de pedido.", "Informar ao PCP a data prometida de chegada — é ela que sustenta o prazo do cliente.", "No recebimento: conferir nota × pedido × material FÍSICO (espessura e cor se confere na chapa, não no papel).", "Recusar o que veio errado ou danificado NA HORA, com foto, antes de assinar o canhoto.", "Dar entrada no estoque e guardar no lugar certo, com a face de vista protegida.", "Encaminhar a nota ao Financeiro para o lançamento no centro de custo."]}, {"tipo": "subtitulo", "texto": "Pontos de atenção"}, {"tipo": "lista", "itens": ["Chapa de ACM e acrílico riscam no descarregamento → sempre em pé, nunca arrastada.", "Espessura vem errada com frequência → medir com paquímetro, não confiar na etiqueta.", "Vinil e lona têm lote: mesma cor em lotes diferentes pode variar → em peça grande, exigir lote único.", "Consumível esquecido (fresa, bico, lâmina) para a máquina inteira → tratar como item crítico de estoque.", "Comprar sem informar o PCP → o prazo do cliente é prometido no escuro."]}, {"tipo": "subtitulo", "texto": "Checklist final"}, {"tipo": "checklist", "itens": ["Estoque conferido antes de cotar", "Cotação com prazo e frete comparados", "Ordem registrada no Mubisys com a O.S.", "PCP informado da data de chegada", "Recebimento conferido no físico (medida, cor, quantidade, avaria)", "Entrada dada e material guardado protegido", "Nota encaminhada ao Financeiro"]}, {"tipo": "subtitulo", "texto": "Registro"}, {"tipo": "lista", "itens": ["Ordem de compra no Mubisys.", "Foto de avaria, quando houver recusa.", "Entrada de estoque com o nº da O.S., quando for de pedido."]}], "versao": "1.0", "revisadoEm": "2026-08-04T12:00:00.000Z", "revisadoPor": "Semente inicial"}$json$::jsonb, now()) on conflict (colecao, id) do update set registro = excluded.registro, atualizado_em = now(), apagado = false;
insert into pops_registros (colecao, id, registro, atualizado_em) values ('pops', 'pop-imp-01', $json${"id": "pop-imp-01", "codigo": "POP-IMP-01", "setor": "Impressão digital e recorte", "titulo": "Impressão, recorte e liberação da peça", "objetivo": "Toda peça impressa sai na cor combinada, na medida final da O.S. e pronta para o acabamento — sem retrabalho de material.", "responsavel": "Operador de impressão", "epis": ["Luva (manuseio de vinil e lona)", "Máscara (troca de tinta solvente)"], "blocos": [{"tipo": "subtitulo", "texto": "Quando se aplica"}, {"tipo": "lista", "itens": ["Qualquer peça em vinil adesivo, lona ou chapa rígida impressa.", "Recorte de vinil de cor (sem impressão) e recorte de contorno."]}, {"tipo": "subtitulo", "texto": "Materiais e equipamentos"}, {"tipo": "lista", "itens": ["Ampla e MyPrint (rolo, solvente/eco-solvente): lona e vinil.", "Impressora UV: impressão direta em chapa rígida.", "Plotter de recorte: contorno e vinil de cor.", "Consumíveis: tinta, lâmina, fita de transporte, álcool isopropílico."]}, {"tipo": "subtitulo", "texto": "Passo a passo"}, {"tipo": "passos", "itens": ["Receber o arquivo liberado pela arte-final com a prancha de produção.", "Conferir arquivo × O.S.: medida FINAL, quantidade, material e onde a peça vai ser aplicada.", "Conferir o material em máquina: tipo, largura, lote e face de impressão.", "Enviar pelo RIP com o PERFIL DO MATERIAL (nunca o perfil genérico).", "Rodar tira de teste: cor, nitidez e ausência de faixas.", "Comparar cor crítica com a referência FÍSICA do cliente, na luz do dia.", "Imprimir o lote acompanhando as primeiras passadas.", "Respeitar a secagem/cura antes de enrolar ou empilhar.", "Recorte: conferir marca de registro, regular pressão e cortar o vinil SEM cortar o liner.", "Descascar e aplicar fita de transporte quando a peça for aplicada inteira.", "Conferir medida final com trena e liberar para o acabamento ou expedição."]}, {"tipo": "subtitulo", "texto": "Pontos de atenção"}, {"tipo": "lista", "itens": ["Faixas claras (banding) → bico entupido ou avanço desregulado; parar e limpar.", "Cor fora → perfil errado, material fora do perfilado ou tinta acabando.", "Peça enrolada úmida → transfere tinta para o verso e perde a peça.", "Recorte cortando o liner → o vinil rasga na aplicação.", "Aprovar cor na tela → monitor mente; só vale a comparação física."]}, {"tipo": "subtitulo", "texto": "Checklist final"}, {"tipo": "checklist", "itens": ["Arquivo confere com a O.S. (medida final e quantidade)", "Perfil de cor do material aplicado", "Tira de teste aprovada antes do lote", "Cor crítica comparada com referência física", "Sem banding, borrado ou marca de roda", "Recorte alinhado com a impressão", "Peça seca antes de enrolar, identificada com a O.S."]}, {"tipo": "subtitulo", "texto": "Registro"}, {"tipo": "lista", "itens": ["Consumo de material por O.S. (metros de lona/vinil).", "Foto da peça impressa quando a cor for crítica."]}], "versao": "1.0", "revisadoEm": "2026-08-04T12:00:00.000Z", "revisadoPor": "Semente inicial"}$json$::jsonb, now()) on conflict (colecao, id) do update set registro = excluded.registro, atualizado_em = now(), apagado = false;
insert into pops_registros (colecao, id, registro, atualizado_em) values ('pops', 'pop-dtf-01', $json${"id": "pop-dtf-01", "codigo": "POP-DTF-01", "setor": "DTF UV e brindes", "titulo": "Aplicação em brindes: DTF UV e gravação", "objetivo": "Brinde entregue com a marca aplicada no mesmo lugar em todas as peças, sem descolar e na quantidade exata do pedido.", "responsavel": "Operador de brindes", "epis": ["Óculos de proteção (laser)", "Luva"], "blocos": [{"tipo": "subtitulo", "texto": "Quando se aplica"}, {"tipo": "lista", "itens": ["Aplicação de marca em copo, garrafa, caneca, caneta, chaveiro e afins.", "Gravação a laser em metal, madeira, couro e acrílico."]}, {"tipo": "subtitulo", "texto": "Escolha da técnica"}, {"tipo": "lista", "itens": ["Logo colorido, degradê ou foto → DTF UV.", "Peça premium, marca discreta e permanente → gravação a laser.", "Objeto escuro com DTF → precisa de branco de apoio, senão a cor some."]}, {"tipo": "subtitulo", "texto": "Passo a passo"}, {"tipo": "passos", "itens": ["Conferir o pedido: quantidade, objeto, cor do objeto e arte.", "Conferir a arte no tamanho REAL da peça — logo pequeno demais some em caneta.", "Fazer UMA peça-piloto completa e conferir com a O.S.", "Na primeira vez com aquele cliente ou objeto, aprovar a piloto antes do lote.", "Limpar o objeto com álcool isopropílico (gordura de mão é a causa nº 1 de adesivo que descola).", "Posicionar com gabarito — nunca no olho: peça torta é a reclamação mais comum de brinde.", "Aplicar (DTF) pressionando do centro para as bordas, ou gravar (laser) com o foco ajustado à curva.", "Conferir por amostragem a cada bandeja.", "Separar as peças com defeito NA HORA.", "Contar o lote antes de embalar e proteger a área aplicada."]}, {"tipo": "subtitulo", "texto": "Pontos de atenção"}, {"tipo": "lista", "itens": ["Copo ou garrafa com verniz solto NÃO segura adesivo → testar uma peça do lote antes de aplicar em centenas.", "Plástico com cloro NÃO entra no laser (mesma regra do PVC).", "Objeto redondo precisa de rotativo ou berço, senão a marca sai torta e sem foco.", "Madeira gravada com potência demais solta fuligem que suja a mão do cliente.", "Contagem errada gera nova viagem: brinde se conta em unidade, sempre."]}, {"tipo": "subtitulo", "texto": "Checklist final"}, {"tipo": "checklist", "itens": ["Peça-piloto aprovada antes do lote", "Gabarito usado — posição igual em todas", "Objeto limpo com isopropílico antes da aplicação", "Amostragem conferida durante o lote", "Defeituosas separadas", "Contagem confere com a O.S.", "Embalagem protege a área aplicada"]}, {"tipo": "subtitulo", "texto": "Registro"}, {"tipo": "lista", "itens": ["Foto da peça-piloto aprovada.", "Quantidade produzida e refugo, por O.S."]}], "versao": "1.0", "revisadoEm": "2026-08-04T12:00:00.000Z", "revisadoPor": "Semente inicial"}$json$::jsonb, now()) on conflict (colecao, id) do update set registro = excluded.registro, atualizado_em = now(), apagado = false;
insert into pops_registros (colecao, id, registro, atualizado_em) values ('pops', 'pop-cor-01', $json${"id": "pop-cor-01", "codigo": "POP-COR-01", "setor": "Corte de chapas e usinagem", "titulo": "Corte de chapas: seccionadora, router e laser CO2", "objetivo": "Peça cortada na medida do projeto, com a face de vista intacta e o melhor aproveitamento possível da chapa.", "responsavel": "Operador de corte", "epis": ["Óculos de proteção", "Protetor auricular", "Luva (manuseio de chapa)"], "blocos": [{"tipo": "subtitulo", "texto": "Quando se aplica"}, {"tipo": "lista", "itens": ["Corte de ACM, PVC expandido, acrílico, MDF e poliondas.", "Usinagem de contorno, furo e rebaixo para letras, portas e placas."]}, {"tipo": "subtitulo", "texto": "Qual máquina para quê"}, {"tipo": "lista", "itens": ["Seccionadora — corte reto em chapa grande; dá o esquadro base.", "Router CNC — contorno, curva, furo interno, rebaixo. É a máquina da letra e da porta.", "Laser CO2 — acrílico com borda polida, sem lixar."]}, {"tipo": "alerta", "texto": "PVC NUNCA entra no laser: libera cloro, corrói a máquina e faz mal a quem respira. Na dúvida entre PVC e acrílico, pergunte ao almoxarifado ANTES de ligar."}, {"tipo": "subtitulo", "texto": "Passo a passo"}, {"tipo": "passos", "itens": ["Conferir arquivo × O.S.: medida final, quantidade e material.", "Conferir se os vetores estão fechados (contorno aberto vira peça perdida).", "Conferir a chapa: espessura com paquímetro, sem empeno, sem risco na face de vista.", "Montar o plano de corte aproveitando a chapa (nesting).", "Marcar qual é a face de vista — a proteção dela só sai no fim.", "Conferir fresa/lâmina/lente: fresa cega queima a borda; lente suja tira potência.", "Cortar UMA peça e conferir a medida ANTES do lote inteiro.", "Acompanhar o corte — nunca deixar a máquina sozinha.", "Rebarbar e identificar cada peça com o nº da O.S. e a posição.", "Separar por destino: Metalurgia, Pintura ou célula de Portas.", "Guardar o retalho aproveitável com a medida escrita."]}, {"tipo": "subtitulo", "texto": "Pontos de atenção"}, {"tipo": "lista", "itens": ["Cortar o lote sem conferir a primeira peça → chapa inteira perdida.", "Tirar o filme de proteção no corte → peça riscada.", "Peça sem identificação → montagem parada adivinhando.", "Retalho no chão → compra de chapa que não precisava.", "Avanço errado no router: derrete PVC, descola o ACM e queima o acrílico."]}, {"tipo": "subtitulo", "texto": "Checklist final"}, {"tipo": "checklist", "itens": ["Primeira peça conferida contra a O.S.", "Face de vista com proteção intacta", "Todas as peças rebarbadas", "Peças identificadas com O.S. e posição", "Retalho guardado e medido", "Consumo de chapa registrado"]}, {"tipo": "subtitulo", "texto": "Registro"}, {"tipo": "lista", "itens": ["Consumo de chapa por O.S.", "Retalho gerado, com medida."]}], "versao": "1.0", "revisadoEm": "2026-08-04T12:00:00.000Z", "revisadoPor": "Semente inicial"}$json$::jsonb, now()) on conflict (colecao, id) do update set registro = excluded.registro, atualizado_em = now(), apagado = false;
insert into pops_registros (colecao, id, registro, atualizado_em) values ('pops', 'pop-pin-01', $json${"id": "pop-pin-01", "codigo": "POP-PIN-01", "setor": "Pintura", "titulo": "Pintura de peças de produção", "objetivo": "Peça pintada na cor exata do projeto, com aderência que resiste a sol e chuva, e curada antes de seguir.", "responsavel": "Pintor", "epis": ["Máscara com filtro para vapores orgânicos", "Luva nitrílica", "Óculos", "Avental"], "blocos": [{"tipo": "alerta", "texto": "A máscara da pintura é a de VAPORES ORGÂNICOS (carvão ativado) — a máscara de poeira não protege de solvente. Pintar sem ela é intoxicação lenta."}, {"tipo": "subtitulo", "texto": "Quando se aplica"}, {"tipo": "lista", "itens": ["Peças vindas da Metalurgia e do Corte, antes da Montagem.", "Estruturas, quadros de porta, letras e suportes."]}, {"tipo": "subtitulo", "texto": "Materiais"}, {"tipo": "lista", "itens": ["Desengraxante, lixas (220/320/400/600), thinner e álcool isopropílico.", "Primer conforme o material: antiferrugem (ferroso), aderência (galvanizado/alumínio/PVC), selador (MDF).", "Tinta PU bicomponente (padrão para peça externa), esmalte sintético, verniz PU.", "Pistola, compressor com filtro de água, papelão de teste."]}, {"tipo": "subtitulo", "texto": "Passo a passo"}, {"tipo": "passos", "itens": ["Conferir a peça contra a O.S.: quantidade e o CÓDIGO da cor (nunca \"azul parecido\").", "Desengraxar: pano limpo, nunca o da bancada.", "Lixar para dar ancoragem; selar borda de MDF; fosquear acrílico e PVC de leve.", "Remover TODO o pó (pano com thinner; soprar só espalha).", "Aplicar o primer do material e respeitar a cura antes de lixar.", "Testar aderência do primer: fita crepe forte num canto escondido — saiu primer, volte uma etapa.", "Misturar a tinta com o catalisador na proporção EXATA (copo graduado, não olhômetro) e coar.", "Regular a pistola no papelão e aplicar demãos FINAS e cruzadas, a 15–20 cm, perpendicular.", "Respeitar o intervalo entre demãos do fabricante.", "Deixar curar antes de manusear (24 h) e antes de adesivar (72 h no PU).", "Conferir sob luz rasante: poeira, dedo, escorrido.", "Anotar o código da cor na O.S. para retoque futuro."]}, {"tipo": "subtitulo", "texto": "Pontos de atenção"}, {"tipo": "lista", "itens": ["Superfície engordurada → a tinta abre \"olho de peixe\".", "Catalisador no olho → não cura ou trinca.", "Escorrido → NÃO passe o dedo; deixe secar, lixe 600 e retoque.", "Pintar com vento ou poeira → acabamento perdido.", "Adesivar antes da cura → o vinil arranca a tinta depois.", "MDF externo sem selar borda → incha na primeira chuva."]}, {"tipo": "subtitulo", "texto": "Checklist final"}, {"tipo": "checklist", "itens": ["Cor conferida pelo código da O.S., na luz do dia", "Sem marca de dedo, poeira ou escorrido sob luz rasante", "Topo e base pintados (as faces que mais pegam água)", "Cura respeitada antes de embalar/adesivar", "Código da cor anotado na O.S."]}, {"tipo": "subtitulo", "texto": "Registro"}, {"tipo": "lista", "itens": ["Código da cor por O.S.", "Consumo de tinta e catalisador."]}], "versao": "1.0", "revisadoEm": "2026-08-04T12:00:00.000Z", "revisadoPor": "Semente inicial"}$json$::jsonb, now()) on conflict (colecao, id) do update set registro = excluded.registro, atualizado_em = now(), apagado = false;
insert into pops_registros (colecao, id, registro, atualizado_em) values ('pops', 'pop-mtg-01', $json${"id": "pop-mtg-01", "codigo": "POP-MTG-01", "setor": "Montagem de letras", "titulo": "Montagem de letra caixa e teste elétrico", "objetivo": "Letra montada com frente, corpo e LED no esquadro, testada ACESA, e embalada de forma que chegue inteira na obra.", "responsavel": "Montador", "epis": ["Luva limpa", "Óculos de proteção"], "blocos": [{"tipo": "subtitulo", "texto": "Quando se aplica"}, {"tipo": "lista", "itens": ["Letra caixa cega e luminosa (frontal, halo ou lateral).", "Peças vindas do Corte, da Metalurgia e da Pintura."]}, {"tipo": "subtitulo", "texto": "Passo a passo"}, {"tipo": "passos", "itens": ["Conferir as peças contra o projeto: quantidade, profundidade e cor.", "Conferir a numeração das peças — letra sem identificação vira quebra-cabeça.", "Montar corpo + frente mantendo profundidade IGUAL em todas as letras do conjunto (o olho percebe 2 mm na sombra).", "Peça luminosa: conferir o interior branco (é ele que rende a luz).", "Distribuir os módulos de LED respeitando a distância face–LED do projeto.", "Dimensionar a fonte com ~20% de folga e cabear em paralelo, respeitando a polaridade.", "Emendas soldadas e isoladas; furo de passagem do cabo com passa-fio vedado.", "Prever o dreno (furinho baixo) em letra externa — condensação mata LED.", "TESTE ELÉTRICO na bancada: energizar e conferir TODAS acesas, luz uniforme, sem mancha.", "Etiquetar: \"LIGAR SOMENTE NA FONTE\".", "Imprimir o gabarito 1:1 do conjunto e embalar as letras INDIVIDUALMENTE."]}, {"tipo": "subtitulo", "texto": "Pontos de atenção"}, {"tipo": "lista", "itens": ["LED colado sem teste → letra apagada na entrega e desmontagem no cliente.", "Fonte subdimensionada → luz fraca e fonte quente.", "Interior escuro em letra luminosa → luz morta.", "Sem dreno em letra externa → LED morto em 3 meses.", "Letras embaladas encostando → risco na face.", "Cola escorrida na face → aparece de noite, iluminada."]}, {"tipo": "subtitulo", "texto": "Checklist final"}, {"tipo": "checklist", "itens": ["Profundidade uniforme no conjunto", "Todas as letras testadas ACESAS (se luminosas)", "Fonte com folga de potência e acessível", "Etiqueta \"ligar somente na fonte\"", "Gabarito 1:1 impresso junto com a peça", "Fixadores, buchas e espaçadores no kit da O.S.", "Embalagem individual, com o nº da O.S."]}, {"tipo": "subtitulo", "texto": "Registro"}, {"tipo": "lista", "itens": ["Foto do conjunto ACESO na bancada, antes de embalar.", "Modelo e potência da fonte, na O.S."]}], "versao": "1.0", "revisadoEm": "2026-08-04T12:00:00.000Z", "revisadoPor": "Semente inicial"}$json$::jsonb, now()) on conflict (colecao, id) do update set registro = excluded.registro, atualizado_em = now(), apagado = false;
insert into pops_registros (colecao, id, registro, atualizado_em) values ('pops', 'pop-por-01', $json${"id": "pop-por-01", "codigo": "POP-POR-01", "setor": "Portas de ACM", "titulo": "Produção de porta de ACM: do corte à ferragem", "objetivo": "Porta no esquadro, com folga uniforme, que abre e fecha com um dedo — e continua assim daqui a dez anos.", "responsavel": "Montador de portas", "epis": ["Luva", "Óculos de proteção", "Protetor auricular"], "blocos": [{"tipo": "subtitulo", "texto": "Quando se aplica"}, {"tipo": "lista", "itens": ["Portas de ACM e revestimentos da linha Arquitetônica."]}, {"tipo": "subtitulo", "texto": "Passo a passo"}, {"tipo": "passos", "itens": ["Medir o VÃO no local: largura em 3 alturas, altura nos 2 lados e as DIAGONAIS.", "Conferir prumo e nível do vão — vão torto muda o projeto da folha.", "Definir com o cliente o sentido de abertura e onde ficam dobradiça e fechadura.", "Cortar e dobrar conforme o projeto, mantendo a face de vista protegida.", "Montar o quadro na bancada plana, travado, e conferir as DIAGONAIS antes de fixar de vez.", "Reforçar internamente o ponto da fechadura.", "Fixar o fechamento do centro para as bordas, para não ondular.", "Instalar ferragens: dobradiças alinhadas no mesmo eixo; 3 dobradiças acima de ~20 kg.", "TESTE DE BANCADA: abrir e fechar 10 vezes ANTES da pintura.", "Enviar para a Pintura conforme o POP-PIN-01 (topo e base também).", "Remontar ferragens após a cura e testar todas as chaves.", "Embalar em pé, amarrada e protegida."]}, {"tipo": "subtitulo", "texto": "Pontos de atenção"}, {"tipo": "lista", "itens": ["Medida por telefone → folha que não entra no vão.", "Diagonais diferentes → porta que não fecha; resolver no projeto, não no improviso.", "Fechadura aberta depois da pintura → risco e retrabalho de pintura inteiro.", "Correr sem guia inferior → porta batendo com o vento na primeira semana.", "Entregar sem testar todas as chaves → assistência no dia seguinte."]}, {"tipo": "subtitulo", "texto": "Checklist final"}, {"tipo": "checklist", "itens": ["Diagonais iguais (±2 mm)", "Folgas uniformes ao redor da folha", "Reforço no ponto da fechadura", "Abre e fecha com um dedo, sem arrastar", "Todas as chaves testadas", "Topo e base pintados", "Kit completo: batente/trilho, ferragens, parafusos, buchas e chaves"]}, {"tipo": "subtitulo", "texto": "Registro"}, {"tipo": "lista", "itens": ["Medidas do vão registradas na O.S.", "Foto da porta montada antes do transporte."]}], "versao": "1.0", "revisadoEm": "2026-08-04T12:00:00.000Z", "revisadoPor": "Semente inicial"}$json$::jsonb, now()) on conflict (colecao, id) do update set registro = excluded.registro, atualizado_em = now(), apagado = false;
insert into pops_registros (colecao, id, registro, atualizado_em) values ('pops', 'pop-acb-01', $json${"id": "pop-acb-01", "codigo": "POP-ACB-01", "setor": "Acabamento", "titulo": "Acabamento de lona: bainha, emenda e ilhós", "objetivo": "Peça impressa que aguenta vento e chuva: bainha soldada, emenda invisível e ilhós que não arranca.", "responsavel": "Operador de acabamento", "epis": ["Luva (superfície quente)", "Óculos"], "blocos": [{"tipo": "subtitulo", "texto": "Quando se aplica"}, {"tipo": "lista", "itens": ["Lona impressa (banner, fachada, testeira), faixas e telas.", "Refile de peças impressas e colocação de ilhós."]}, {"tipo": "subtitulo", "texto": "Materiais"}, {"tipo": "lista", "itens": ["Carrinho de soldar lona / máquina de solda, régua e estilete de refile.", "Ilhós, matriz e prensa; fita de reforço."]}, {"tipo": "subtitulo", "texto": "Passo a passo"}, {"tipo": "passos", "itens": ["Conferir a medida FINAL da O.S. — a peça impressa vem com sobra de propósito.", "Refilar sobre superfície plana, com guia; corte torto aparece de longe.", "Marcar a dobra da bainha (3 a 5 cm, conforme o tamanho da peça).", "Testar temperatura e velocidade num RETALHO do mesmo material.", "Soldar a bainha e conferir puxando com a mão.", "Emenda: alinhar pela ARTE (o desenho continua), sobrepor 2 a 3 cm e soldar sem parar no meio.", "Conferir a emenda contra a luz — falha aparece como ponto claro.", "Reforçar as pontas da emenda e os cantos.", "Ilhós a cada 40–50 cm (menos em vento forte), SEMPRE na dupla camada da bainha.", "Conferir cada ilhós: nenhum girando ou solto.", "Dobrar com a arte para dentro e identificar com a O.S."]}, {"tipo": "subtitulo", "texto": "Pontos de atenção"}, {"tipo": "lista", "itens": ["Temperatura alta → queima a lona (amarela e quebradiça na dobra).", "Temperatura baixa → a solda abre depois, no cliente.", "Ilhós na lona simples → rasga no primeiro vento.", "Emenda alinhada pela borda em vez da arte → o desenho quebra.", "Peça dobrada com a arte para fora → risco na impressão."]}, {"tipo": "subtitulo", "texto": "Checklist final"}, {"tipo": "checklist", "itens": ["Medida final conferida com trena", "Bainha soldada em toda a volta, testada com a mão", "Emenda alinhada pela arte e sem falha contra a luz", "Ilhós na dupla camada, espaçamento uniforme", "Cantos reforçados", "Peça dobrada com a arte para dentro, identificada"]}, {"tipo": "subtitulo", "texto": "Registro"}, {"tipo": "lista", "itens": ["Metragem acabada por O.S.", "Quantidade de ilhós utilizada."]}], "versao": "1.0", "revisadoEm": "2026-08-04T12:00:00.000Z", "revisadoPor": "Semente inicial"}$json$::jsonb, now()) on conflict (colecao, id) do update set registro = excluded.registro, atualizado_em = now(), apagado = false;
insert into pops_registros (colecao, id, registro, atualizado_em) values ('pops', 'pop-mkt-01', $json${"id": "pop-mkt-01", "codigo": "POP-MKT-01", "setor": "Marketing", "titulo": "Registro de obra e publicação de case", "objetivo": "Toda obra boa vira material de venda: foto certa, autorização do cliente e publicação que traz o próximo pedido.", "responsavel": "Marketing", "epis": [], "blocos": [{"tipo": "subtitulo", "texto": "Quando se aplica"}, {"tipo": "lista", "itens": ["Toda instalação concluída com resultado apresentável.", "Peças de destaque: fachada, letreiro luminoso, porta, envelopamento."]}, {"tipo": "subtitulo", "texto": "A foto que vende (e a que não vende)"}, {"tipo": "lista", "itens": ["Frontal, a 5–10 m, com a fachada inteira no quadro — é assim que o cliente vê da rua.", "Luminoso: foto ao ENTARDECER, com a luz acesa. Foto de luminoso apagado não vende luminoso.", "Antes e depois, do MESMO ângulo — é o par que mais converte.", "Sem carro na frente, sem lixo, sem escada aparecendo.", "Detalhe do acabamento em close: é ele que separa a Impresilk do concorrente barato."]}, {"tipo": "subtitulo", "texto": "Passo a passo"}, {"tipo": "passos", "itens": ["Combinar com a equipe de instalação as fotos do checklist (POP-MONT-01) — elas já vêm da obra.", "Pedir a foto do LOCAL VAZIO antes: sem ela não existe \"antes e depois\".", "Confirmar com o Comercial se o cliente autoriza a divulgação (alguns não autorizam por contrato ou por marca).", "Selecionar as 3 a 5 melhores e tratar: enquadramento, horizonte no nível, cor fiel.", "Escrever o case: o problema do cliente, a solução aplicada, o material e o prazo.", "Publicar no Instagram e adicionar ao portfólio do site.", "Marcar o cliente quando ele autorizar — é o que gera indicação.", "Arquivar as fotos com o nº da O.S. para o portfólio e para futuras propostas."]}, {"tipo": "subtitulo", "texto": "Pontos de atenção"}, {"tipo": "lista", "itens": ["Publicar sem autorização → problema com o cliente e com a marca dele.", "Foto tirada de baixo, torta → a peça parece torta mesmo estando reta.", "Luminoso fotografado de dia → some o produto que se está vendendo.", "Case sem o \"problema resolvido\" → vira foto bonita, não argumento de venda."]}, {"tipo": "subtitulo", "texto": "Checklist final"}, {"tipo": "checklist", "itens": ["Autorização do cliente confirmada com o Comercial", "Foto frontal a 5–10 m", "Luminoso fotografado aceso, ao entardecer", "Par antes/depois do mesmo ângulo", "Texto do case com problema, solução, material e prazo", "Arquivado com o nº da O.S."]}, {"tipo": "subtitulo", "texto": "Registro"}, {"tipo": "lista", "itens": ["Pasta do case com o nº da O.S.", "Data da publicação e autorização do cliente."]}], "versao": "1.0", "revisadoEm": "2026-08-04T12:00:00.000Z", "revisadoPor": "Semente inicial"}$json$::jsonb, now()) on conflict (colecao, id) do update set registro = excluded.registro, atualizado_em = now(), apagado = false;
insert into pops_registros (colecao, id, registro, atualizado_em) values ('pops', 'pop-psv-01', $json${"id": "pop-psv-01", "codigo": "POP-PSV-01", "setor": "Pós-venda", "titulo": "Atendimento de garantia e manutenção de fachada", "objetivo": "Reclamação vira solução rápida e rastreável: causa identificada, responsabilidade clara e cliente informado em 24 h.", "responsavel": "Pós-venda", "epis": [], "blocos": [{"tipo": "subtitulo", "texto": "Quando se aplica"}, {"tipo": "lista", "itens": ["Peça com defeito dentro da garantia.", "Manutenção preventiva ou limpeza de fachada.", "Peça danificada por terceiros ou intempérie (fora de garantia, vira orçamento)."]}, {"tipo": "subtitulo", "texto": "Passo a passo"}, {"tipo": "passos", "itens": ["Registrar o chamado com: cliente, nº da O.S. original, data da instalação e o que está acontecendo.", "Pedir FOTO ao cliente antes de agendar — metade dos chamados se resolve por telefone.", "Responder em até 24 h, mesmo que seja para dizer \"vamos até aí na terça\".", "Consultar a O.S. original: material, fixação usada, quem instalou e o registro fotográfico.", "Classificar a causa: defeito de fabricação · falha de instalação · uso indevido · intempérie/terceiro.", "Garantia (fabricação ou instalação) → agendar o reparo sem custo e informar a produção.", "Fora de garantia → orçar como serviço, explicando ao cliente por que não é garantia.", "Executar seguindo o POP de instalação, com o mesmo checklist fotográfico.", "Fechar o chamado com foto do reparo e confirmação do cliente.", "Devolver a causa raiz ao setor de origem — é isso que impede a repetição."]}, {"tipo": "subtitulo", "texto": "Casos que mais aparecem"}, {"tipo": "lista", "itens": ["LED apagado → quase sempre o cliente ligou direto na tomada, sem a fonte (ver POP-MONT-04).", "Adesivo descolando na borda → superfície suja na aplicação ou material vencido.", "Lona rasgada no ilhós → ilhós fora da bainha ou espaçamento largo demais.", "Fachada infiltrando → junta sem silicone neutro."]}, {"tipo": "subtitulo", "texto": "Pontos de atenção"}, {"tipo": "lista", "itens": ["Demorar a responder é pior que a falha em si.", "Prometer garantia sem consultar a O.S. → custo que não era nosso.", "Resolver e não avisar o setor de origem → o mesmo erro volta no mês seguinte."]}, {"tipo": "subtitulo", "texto": "Checklist final"}, {"tipo": "checklist", "itens": ["Chamado registrado com o nº da O.S. original", "Foto do cliente recebida antes do agendamento", "Resposta dada em até 24 h", "Causa classificada", "Reparo executado com checklist fotográfico", "Cliente confirmou", "Causa raiz devolvida ao setor de origem"]}, {"tipo": "subtitulo", "texto": "Registro"}, {"tipo": "lista", "itens": ["Chamado com causa e desfecho.", "Fotos antes e depois do reparo."]}], "versao": "1.0", "revisadoEm": "2026-08-04T12:00:00.000Z", "revisadoPor": "Semente inicial"}$json$::jsonb, now()) on conflict (colecao, id) do update set registro = excluded.registro, atualizado_em = now(), apagado = false;
insert into pops_registros (colecao, id, registro, atualizado_em) values ('pops', 'pop-arf-01', $json${"id": "pop-arf-01", "codigo": "POP-ARF-01", "setor": "Arte-final e pré-impressão", "titulo": "Fechamento de arquivo e prancha de produção", "objetivo": "Arquivo que entra na máquina sem ajuste: medida final, cor no perfil certo, sangria e corte marcados — e a prancha que a fábrica lê.", "responsavel": "Arte-finalista", "epis": [], "blocos": [{"tipo": "subtitulo", "texto": "Quando se aplica"}, {"tipo": "lista", "itens": ["Toda arte aprovada pelo cliente que vai para produção.", "Geração de prancha de produção para os setores de fábrica."]}, {"tipo": "subtitulo", "texto": "O que é \"arquivo fechado\""}, {"tipo": "lista", "itens": ["Medida FINAL da peça, na escala combinada (1:1 quando possível).", "Resolução adequada à distância de leitura (fachada não precisa da resolução de um adesivo).", "Fontes convertidas em curvas.", "Cor no perfil do material que será usado.", "Sangria e linha de corte/refile marcadas.", "Contorno de recorte em camada própria, vetores fechados."]}, {"tipo": "subtitulo", "texto": "Passo a passo"}, {"tipo": "passos", "itens": ["Receber a arte aprovada e a O.S.; conferir se a aprovação é a versão FINAL.", "Conferir a medida contra a O.S. e contra a medição da visita — divergência volta ao Comercial.", "Converter cores para o perfil do material e sinalizar cor crítica da marca do cliente.", "Aplicar sangria e marcar corte/refile conforme o acabamento previsto.", "Preparar o recorte de contorno (quando houver) em camada separada.", "Fazer o nesting quando a peça for cortada em chapa, para aproveitar material.", "Gerar a PRANCHA DE PRODUÇÃO com: cliente, O.S., material, medidas, quantidade e observações da fábrica.", "Nomear o arquivo no padrão da casa (O.S. + cliente + peça + versão).", "Salvar na pasta de APROVADOS — só o que está lá pode ir para a máquina.", "Liberar para o setor de produção correspondente."]}, {"tipo": "subtitulo", "texto": "Pontos de atenção"}, {"tipo": "lista", "itens": ["Arte boa em 30 cm pode ser lixo em 3 m → conferir resolução na medida REAL.", "Fonte não convertida → a máquina troca a fonte e ninguém percebe até a peça pronta.", "Vetor aberto no recorte → contorno errado e peça perdida.", "Versão errada aplicada → pasta de aprovados separada resolve.", "Prancha sem observação da fábrica → o operador decide sozinho o que não é dele decidir."]}, {"tipo": "subtitulo", "texto": "Checklist final"}, {"tipo": "checklist", "itens": ["Medida final conferida contra a O.S.", "Resolução adequada à distância de leitura", "Fontes em curvas", "Perfil de cor do material aplicado; cor crítica sinalizada", "Sangria e corte marcados", "Contorno em camada própria, vetores fechados", "Prancha de produção gerada", "Arquivo na pasta de aprovados, nomeado no padrão"]}, {"tipo": "subtitulo", "texto": "Registro"}, {"tipo": "lista", "itens": ["Prancha de produção anexada à O.S.", "Versão do arquivo aprovado."]}], "versao": "1.0", "revisadoEm": "2026-08-04T12:00:00.000Z", "revisadoPor": "Semente inicial"}$json$::jsonb, now()) on conflict (colecao, id) do update set registro = excluded.registro, atualizado_em = now(), apagado = false;
insert into pops_registros (colecao, id, registro, atualizado_em) values ('pops', 'pop-prj-01', $json${"id": "pop-prj-01", "codigo": "POP-PRJ-01", "setor": "Projetos técnicos", "titulo": "Projeto de estrutura e memorial", "objetivo": "Estrutura dimensionada para o vento e para o peso reais do local, com fixação definida e memorial que a fábrica e o instalador conseguem executar.", "responsavel": "Projetista", "epis": [], "blocos": [{"tipo": "subtitulo", "texto": "Quando se aplica"}, {"tipo": "lista", "itens": ["Fachadas, letreiros com estrutura, totens, portas e revestimentos.", "Qualquer peça acima de 3 m de altura ou com peso relevante."]}, {"tipo": "subtitulo", "texto": "O que o projeto precisa definir"}, {"tipo": "lista", "itens": ["Medidas finais e a estrutura (bitola do metalon, chapa, perfil).", "Fixação: tipo de superfície, fixador, quantidade e espaçamento.", "Peso total e o ponto de apoio.", "Se leva iluminação: posição do LED, da fonte e o caminho do fio.", "Acabamento: cor e onde é pintado."]}, {"tipo": "subtitulo", "texto": "Passo a passo"}, {"tipo": "passos", "itens": ["Conferir a medição da visita (Brief) e as fotos do local.", "Identificar a superfície de fixação — alvenaria, drywall, vidro, ACM, cerâmica, telha, madeira.", "Dimensionar a estrutura pelo VÃO e pelo peso, não pelo que sobrou no estoque.", "Definir a fixação compatível com a superfície e com o peso, com folga de segurança.", "Prever dilatação e drenagem em peça externa (metal esquenta; água entra).", "Desenhar o corte do metalon e o plano de solda para a Metalurgia.", "Gerar o memorial: lista de material, sequência de montagem e sequência de instalação.", "Submeter ao PCP para aprovação antes de liberar para a fábrica.", "Liberar para a Metalurgia/Corte com o projeto aprovado anexado à O.S."]}, {"tipo": "subtitulo", "texto": "Pontos de atenção"}, {"tipo": "lista", "itens": ["Projetar sem foto do local → surpresa na instalação.", "Ignorar o vento em fachada alta → estrutura que trabalha e solda que trinca.", "Fixação escolhida no papel sem confirmar a superfície → equipe furando e improvisando na obra.", "Peça externa sem dreno → água acumulada e ferrugem por dentro.", "Memorial sem sequência → a fábrica monta na ordem errada e desmonta para corrigir."]}, {"tipo": "subtitulo", "texto": "Checklist final"}, {"tipo": "checklist", "itens": ["Medição e fotos do local conferidas", "Superfície de fixação identificada", "Estrutura dimensionada para peso e vento", "Fixação definida com quantidade e espaçamento", "Dilatação e drenagem previstas", "Memorial com material e sequência", "Aprovado pelo PCP antes de liberar"]}, {"tipo": "subtitulo", "texto": "Registro"}, {"tipo": "lista", "itens": ["Projeto e memorial anexados à O.S.", "Aprovação do PCP registrada."]}], "versao": "1.0", "revisadoEm": "2026-08-04T12:00:00.000Z", "revisadoPor": "Semente inicial"}$json$::jsonb, now()) on conflict (colecao, id) do update set registro = excluded.registro, atualizado_em = now(), apagado = false;
insert into pops_registros (colecao, id, registro, atualizado_em) values ('pops', 'pop-rh-01', $json${"id": "pop-rh-01", "codigo": "POP-RH-01", "setor": "RH e DP", "titulo": "Integração de novo colaborador", "objetivo": "Pessoa nova produzindo com segurança na primeira semana: documentos em ordem, EPI na mão, acessos criados e POPs do setor lidos.", "responsavel": "RH e DP", "epis": [], "blocos": [{"tipo": "subtitulo", "texto": "Quando se aplica"}, {"tipo": "lista", "itens": ["Toda contratação, inclusive temporária e de experiência."]}, {"tipo": "subtitulo", "texto": "Passo a passo — antes do primeiro dia"}, {"tipo": "passos", "itens": ["Fechar a documentação e o registro em folha.", "Separar os EPIs do setor e a ficha de entrega de EPI (NR-06).", "Pedir ao TI a criação dos acessos aos sistemas que a função exige.", "Avisar o gestor do setor e definir quem será o padrinho da pessoa."]}, {"tipo": "subtitulo", "texto": "Primeiro dia"}, {"tipo": "passos", "itens": ["Apresentar a empresa: o que a Impresilk faz, as 4 linhas de produção e onde a função dela entra.", "Entregar os EPIs contra assinatura e explicar o uso de cada um.", "Treinar segurança do setor: máquinas, riscos e o que NÃO se faz.", "Apresentar aos setores vizinhos — de quem recebe e para quem entrega.", "Criar o acesso ao Pops & Fabricação e mostrar como consultar os POPs na bancada."]}, {"tipo": "subtitulo", "texto": "Primeira semana"}, {"tipo": "passos", "itens": ["Definir os POPs obrigatórios do setor e acompanhar a leitura no mapa de treinamento.", "Iniciar a jornada de fabricação da função (Corte, Metalurgia, Pintura, Montagem, Impressão, Acabamento ou Brindes).", "Acompanhamento diário do padrinho.", "Ao fim da semana: conversa de alinhamento com o gestor."]}, {"tipo": "subtitulo", "texto": "Pontos de atenção"}, {"tipo": "lista", "itens": ["Pessoa em máquina sem treinamento de segurança → acidente e responsabilidade da empresa.", "EPI entregue sem assinatura → não existe comprovação legal.", "Acesso criado depois → a pessoa passa a semana pedindo favor para os outros.", "Sem padrinho definido → aprende errado com quem estiver por perto."]}, {"tipo": "subtitulo", "texto": "Checklist final"}, {"tipo": "checklist", "itens": ["Documentação e registro concluídos", "EPIs entregues com ficha assinada (NR-06)", "Treinamento de segurança do setor realizado", "Acessos criados (inclusive Pops & Fabricação)", "POPs obrigatórios do setor lidos e registrados", "Jornada de fabricação da função iniciada", "Conversa de alinhamento na primeira semana"]}, {"tipo": "subtitulo", "texto": "Registro"}, {"tipo": "lista", "itens": ["Ficha de entrega de EPI assinada.", "Mapa de treinamento do Pops & Fabricação (leituras e jornadas)."]}], "versao": "1.0", "revisadoEm": "2026-08-04T12:00:00.000Z", "revisadoPor": "Semente inicial"}$json$::jsonb, now()) on conflict (colecao, id) do update set registro = excluded.registro, atualizado_em = now(), apagado = false;
insert into pops_registros (colecao, id, registro, atualizado_em) values ('pops', 'pop-ti-01', $json${"id": "pop-ti-01", "codigo": "POP-TI-01", "setor": "TI e sistemas", "titulo": "Criação e remoção de acesso aos sistemas", "objetivo": "Quem entra tem acesso no primeiro dia; quem sai perde no mesmo dia. Sempre pela Central, sempre com registro.", "responsavel": "TI e sistemas", "epis": [], "blocos": [{"tipo": "subtitulo", "texto": "Quando se aplica"}, {"tipo": "lista", "itens": ["Contratação, mudança de função e desligamento.", "Pedido de acesso a um sistema novo."]}, {"tipo": "subtitulo", "texto": "Os sistemas da casa"}, {"tipo": "lista", "itens": ["Painel de Gestão · RH (Pessoas) · PCP/Instalação · Brief de Medição · DRE Caixa · Compras · Pops & Fabricação.", "Todos com login pela CENTRAL DE ACESSOS — uma conta por pessoa, mesma senha em todos.", "ERP Mubisys tem cadastro próprio, feito à parte."]}, {"tipo": "subtitulo", "texto": "Passo a passo — criar"}, {"tipo": "passos", "itens": ["Receber do RH a função e os sistemas que ela exige.", "Criar a conta na Central de Acessos, com senha TEMPORÁRIA legível.", "Definir o papel em cada sistema (o menor possível para a função).", "Entregar usuário e senha à pessoa por canal direto — a senha troca na primeira entrada.", "Confirmar que a pessoa conseguiu entrar e trocar a senha."]}, {"tipo": "subtitulo", "texto": "Passo a passo — remover"}, {"tipo": "passos", "itens": ["Receber o aviso de desligamento do RH no MESMO dia.", "Desativar a conta em TODOS os sistemas pela Central.", "Conferir no histórico de acessos se houve entrada depois do desligamento.", "Recolher aparelho da empresa e sair da conta nele (\"Sair e limpar\" no Brief).", "Trocar senhas compartilhadas que a pessoa conhecia (a porta do DRE é de todos)."]}, {"tipo": "subtitulo", "texto": "Pontos de atenção"}, {"tipo": "lista", "itens": ["Conta compartilhada entre duas pessoas → o histórico deixa de dizer quem fez o quê.", "Papel maior que a função → alguém apaga o que não devia.", "Desligamento sem desativar → acesso ativo por 30 dias (o crachá dura isso).", "Senha mandada em grupo → deixa de ser senha."]}, {"tipo": "subtitulo", "texto": "Checklist final"}, {"tipo": "checklist", "itens": ["Conta criada na Central, com senha temporária", "Papel mínimo necessário para a função", "Pessoa entrou e trocou a senha", "No desligamento: desativada em todos os sistemas no mesmo dia", "Histórico conferido", "Senhas compartilhadas trocadas"]}, {"tipo": "subtitulo", "texto": "Registro"}, {"tipo": "lista", "itens": ["Histórico de acessos da Central (quem criou, quem removeu e quando)."]}], "versao": "1.0", "revisadoEm": "2026-08-04T12:00:00.000Z", "revisadoPor": "Semente inicial"}$json$::jsonb, now()) on conflict (colecao, id) do update set registro = excluded.registro, atualizado_em = now(), apagado = false;
insert into pops_registros (colecao, id, registro, atualizado_em) values ('pops', 'pop-mnt-01', $json${"id": "pop-mnt-01", "codigo": "POP-MNT-01", "setor": "Manutenção", "titulo": "Manutenção preventiva das máquinas críticas", "objetivo": "Laser fibra, CO2, router e UV rodando — porque máquina parada nessas quatro para uma linha inteira de produção.", "responsavel": "Manutenção", "epis": ["Óculos de proteção", "Luva"], "blocos": [{"tipo": "destaque", "texto": "Prioridade 1 da manutenção: laser fibra, laser CO2, router CNC e impressora UV. Se uma delas para, uma linha inteira para junto."}, {"tipo": "subtitulo", "texto": "Quando se aplica"}, {"tipo": "lista", "itens": ["Rotina preventiva (diária, semanal e mensal).", "Qualquer sintoma de perda de qualidade antes de virar quebra."]}, {"tipo": "subtitulo", "texto": "Rotina diária (o operador faz)"}, {"tipo": "lista", "itens": ["Limpar a mesa e remover resíduo de corte.", "Conferir nível de refrigeração e ar comprimido.", "Limpar lente e conferir bico (laser).", "Conferir fresa e pinça (router).", "Impressora UV: limpeza de cabeçote e teste de bicos ANTES do primeiro trabalho."]}, {"tipo": "subtitulo", "texto": "Rotina semanal"}, {"tipo": "lista", "itens": ["Lubrificar guias e fusos conforme o manual.", "Conferir e limpar filtros da exaustão.", "Conferir folga de eixo (peça saindo fora de medida costuma ser folga, não arquivo).", "Drenar o compressor — água no ar arruína pintura e corte."]}, {"tipo": "subtitulo", "texto": "Rotina mensal"}, {"tipo": "lista", "itens": ["Conferir alinhamento e potência do laser.", "Conferir correias e rolamentos.", "Revisar sistema de tinta da UV e limpeza profunda de cabeçote.", "Testar botões de emergência de TODAS as máquinas."]}, {"tipo": "subtitulo", "texto": "Passo a passo do chamado"}, {"tipo": "passos", "itens": ["Registrar o sintoma com a máquina, o horário e o que estava sendo feito.", "Avisar o PCP na hora — é ele que remaneja a produção.", "Diagnosticar do simples para o complexo (consumível → ajuste → mecânica → eletrônica).", "Executar o reparo ou acionar a assistência, com o custo aprovado pela direção.", "Registrar o que foi feito e a peça trocada.", "Rodar uma peça de teste e liberar a máquina formalmente."]}, {"tipo": "subtitulo", "texto": "Pontos de atenção"}, {"tipo": "lista", "itens": ["Perda de qualidade é aviso de quebra: borda ruim, faixa na impressão e medida fora costumam vir antes da parada.", "Manutenção adiada sempre volta mais cara e no pior dia.", "Máquina liberada sem peça de teste → o problema aparece na peça do cliente.", "Botão de emergência que ninguém testa é decoração."]}, {"tipo": "subtitulo", "texto": "Checklist final"}, {"tipo": "checklist", "itens": ["Rotina diária cumprida nas 4 máquinas críticas", "Semanal e mensal em dia", "Chamados registrados com sintoma e solução", "Peça de teste rodada antes de liberar", "PCP informado de parada e de retorno"]}, {"tipo": "subtitulo", "texto": "Registro"}, {"tipo": "lista", "itens": ["Ficha de manutenção por máquina (data, serviço, peça trocada).", "Histórico de paradas — é ele que mostra qual máquina precisa de investimento."]}], "versao": "1.0", "revisadoEm": "2026-08-04T12:00:00.000Z", "revisadoPor": "Semente inicial"}$json$::jsonb, now()) on conflict (colecao, id) do update set registro = excluded.registro, atualizado_em = now(), apagado = false;
insert into pops_registros (colecao, id, registro, atualizado_em) values ('jornadas', 'jor-expedicao', $json${"id": "jor-expedicao", "titulo": "Embarque e expedição", "ordem": 9, "nivel": "Introdutório", "versao": "1.0", "linha": "linha-letras", "setor": "PCP e Expedição", "descricao": "A peça sai inteira e completa: conferência contra a O.S., embalagem que protege e carga que chega sem avaria.", "revisadoEm": "2026-08-04T12:00:00.000Z", "etapas": [{"id": "et-exp-1", "titulo": "A última chance de pegar o erro", "blocos": [{"tipo": "paragrafo", "texto": "A expedição é o último setor a ver a peça antes do cliente. Tudo que passar daqui vira viagem perdida, equipe parada na obra e reclamação — e nada disso volta."}, {"tipo": "destaque", "texto": "A pergunta da expedição não é \"está pronto?\". É: se eu fosse instalar isso amanhã, com essa caixa, chegaria tudo que eu preciso? Se falta um parafuso, a obra para."}, {"tipo": "subtitulo", "texto": "O que se confere aqui"}, {"tipo": "lista", "itens": ["Quantidade e medidas contra a O.S.", "Kit completo: fixadores, buchas, espaçadores, fonte, chaves e gabarito.", "Peça sem avaria e com a proteção no lugar.", "Identificação: nº da O.S. em toda embalagem."]}]}, {"id": "et-exp-2", "titulo": "Conferência e embalagem", "blocos": [{"tipo": "passos", "itens": ["Conferir a O.S. item a item — não pelo volume aparente.", "Conferir se a peça foi testada onde há teste (letra acesa, porta abrindo).", "Embalar por tipo: letras individualmente com papelão entre elas; ACM em pé com proteção em todas as faces; lona dobrada com a arte para DENTRO.", "Colocar o kit de fixação junto da peça, identificado.", "Incluir o gabarito 1:1 quando houver conjunto de letras.", "Etiquetar cada volume com o nº da O.S., o cliente e \"volume X de Y\"."]}, {"tipo": "alerta", "texto": "Peça sem \"volume X de Y\" é peça que se perde: a equipe leva 2 volumes de 3 e descobre na obra."}]}, {"id": "et-exp-3", "titulo": "Carga, rota e entrega", "blocos": [{"tipo": "passos", "itens": ["Conferir o veículo: espaço, carga amarrada e nada apoiado sobre a face de vista.", "ACM e acrílico viajam EM PÉ, nunca deitados uns sobre os outros.", "Peça luminosa: fonte e cabos em caixa separada e identificada.", "Conferir a rota e o horário combinado com o cliente.", "Registrar a saída (o que saiu, para onde e com quem).", "Na entrega, conferir com quem recebe e colher o aceite."]}, {"tipo": "subtitulo", "texto": "Erros que a gente não repete"}, {"tipo": "lista", "itens": ["Carregar sem conferir a O.S. → falta peça na obra.", "ACM deitado com peso em cima → risco e amassado.", "Kit de fixação esquecido → equipe improvisa e a peça cai depois.", "Sem registro de saída → ninguém sabe o que foi entregue."]}, {"tipo": "checklist", "itens": ["O.S. conferida item a item", "Kit de fixação junto e identificado", "Gabarito incluído (conjunto de letras)", "Volumes etiquetados X de Y", "Carga amarrada, ACM em pé", "Saída registrada"]}]}]}$json$::jsonb, now()) on conflict (colecao, id) do update set registro = excluded.registro, atualizado_em = now(), apagado = false;
insert into pops_registros (colecao, id, registro, atualizado_em) values ('jornadas', 'jor-instalacao', $json${"id": "jor-instalacao", "titulo": "Instalação em campo", "ordem": 10, "nivel": "Avançado", "versao": "1.0", "linha": "linha-letras", "setor": "Instalação de placas", "descricao": "Trabalho em altura com NR-35, vistoria antes de furar e checklist fotográfico: a etapa onde o erro é caro e o risco é real.", "revisadoEm": "2026-08-04T12:00:00.000Z", "etapas": [{"id": "et-ins-1", "titulo": "Segurança em altura não é burocracia", "blocos": [{"tipo": "alerta", "texto": "Acima de 2 m já é trabalho em altura (NR-35). Cinto de segurança com talabarte ancorado em ponto firme, capacete com jugular e treinamento válido. Quem não tem o treinamento NÃO sobe — não é rigor, é a diferença entre voltar para casa e não voltar."}, {"tipo": "subtitulo", "texto": "Antes de subir"}, {"tipo": "lista", "itens": ["Andaime montado e travado, ou escada amarrada e no ângulo certo.", "Ponto de ancoragem conferido — estrutura que segura pessoa, não calha.", "Área isolada embaixo: ferramenta que cai de 6 m mata.", "Ninguém trabalha sozinho em altura.", "Chuva, vento forte ou trovoada: para. A peça espera; a pessoa não se repõe."]}, {"tipo": "destaque", "texto": "A régua da equipe: se alguém não está confortável em subir naquelas condições, a instalação é adiada e o gerente é acionado. Nunca se resolve isso na pressão do dia."}]}, {"id": "et-ins-2", "titulo": "Vistoria: o que se descobre antes de furar", "blocos": [{"tipo": "passos", "itens": ["Conferir a superfície REAL contra o projeto — alvenaria, drywall, vidro, ACM, cerâmica, telha.", "Conferir as medidas do local com trena, contra o projeto.", "Procurar fiação, tubulação e obstáculo oculto antes de escolher o ponto.", "Confirmar o ponto elétrico quando a peça é luminosa (e o que o pedido cobre).", "Divergência de qualquer tipo → parar e acionar o gerente. Nunca improvisar fixação."]}, {"tipo": "paragrafo", "texto": "Esta etapa é curta e evita o retrabalho mais caro da empresa: a peça furada no lugar errado."}]}, {"id": "et-ins-3", "titulo": "Execução e registro", "blocos": [{"tipo": "passos", "itens": ["Marcar os pontos com trena e nível ANTES de furar.", "Conferir de longe (5–10 m) com a peça apoiada, antes da fixação definitiva.", "Fixar com o fixador correto para a superfície identificada.", "Peça luminosa: ligar na FONTE, nunca direto na rede; testar acesa antes de descer.", "Vedar passagem de fio e juntas com silicone neutro.", "Limpar o local e deixar como encontrado.", "Registro obrigatório: foto do local vazio (antes), foto do resultado (depois), relato no grupo com o nº da O.S. e aceite do cliente."]}, {"tipo": "subtitulo", "texto": "Entrega ao cliente"}, {"tipo": "lista", "itens": ["Mostrar a fonte e avisar que ligar direto na tomada queima os LEDs (a garantia não cobre).", "Explicar a manutenção simples: limpeza com pano úmido, sem solvente.", "Registrar a orientação no relato da O.S."]}, {"tipo": "checklist", "itens": ["Treinamento NR-35 válido de quem subiu", "Ancoragem e isolamento da área conferidos", "Vistoria feita antes de furar", "Nível conferido antes e depois", "Peça luminosa testada ACESA no local", "Vedação feita", "Foto antes + foto depois + relato com a O.S. + aceite do cliente"]}]}]}$json$::jsonb, now()) on conflict (colecao, id) do update set registro = excluded.registro, atualizado_em = now(), apagado = false;
